const mediaPlaceholder = (id, title) => ({
  id,
  type: 'audio',
  url: '',
  title: `${title} (аудио не загружено; используйте текст)`,
  mime: '',
  size: 0,
  duration: 0,
  path: '',
})

const richText = (...paragraphs) => paragraphs
  .flat()
  .filter(Boolean)
  .map((paragraph) => `<p>${paragraph}</p>`)
  .join('')

const character = (id, title, subtitle, defaultNodeId, description, startVisible = true) => ({
  id,
  title,
  subtitle,
  descriptionRich: richText(description),
  image: '',
  media: [],
  startVisible,
  hiddenUntilUnlocked: !startVisible,
  defaultNodeId,
  position: { x: 0, y: 0 },
})

const topic = (id, title, startVisible = false) => ({
  id,
  title,
  descriptionRich: '',
  icon: '',
  startVisible,
  hiddenUntilUnlocked: !startVisible,
  position: { x: 0, y: 0 },
})

const evidence = (id, title, description, tags, isKey = true) => ({
  id,
  title,
  descriptionRich: richText(description),
  media: [],
  tags,
  weight: isKey ? 1 : 0,
  isKey,
  hiddenUntilDiscovered: true,
})

const interaction = ({
  id,
  locationId,
  characterId = null,
  topicId = null,
  label,
  response,
  time = null,
  kind = characterId ? 'question' : 'examine',
  conditions = {},
  effects = {},
  journalKind = characterId ? 'testimony' : 'observation',
}) => {
  const resolvedResponse = literaryDialogueResponses[id] || response

  return {
    id,
    kind,
    locationId,
    characterId,
    topicId,
    label,
    promptRich: '',
    responseRich: richText(resolvedResponse),
    media: [mediaPlaceholder(`media-${id}`, label)],
    timeCostMinutes: time ?? (characterId ? 5 : 10),
    repeatable: false,
    reapplyEffects: false,
    conditions: {
      requiredItemIds: [],
      requiredEvidenceIds: [],
      requiredTopicIds: [],
      requiredCharacterIds: [],
      requiredInteractionIds: [],
      requiredFlagIds: [],
      minElapsedMinutes: null,
      maxElapsedMinutes: null,
      ...conditions,
    },
    effects: {
      grantsItemIds: [],
      consumesItemIds: [],
      grantsEvidenceIds: [],
      unlocksNodeIds: [],
      unlocksCharacterIds: [],
      unlocksTopicIds: [],
      setsFlagIds: [],
      scoreBonus: 0,
      scorePenalty: 0,
      endingId: null,
      ...effects,
    },
    journal: {
      title: label,
      summaryRich: richText(resolvedResponse),
      kind: journalKind,
    },
  }
}

const node = (id, title, description, startVisible, x, y) => ({
  id,
  title,
  descriptionRich: richText(description),
  media: [],
  coordinates: { latitude: null, longitude: null, radius: null },
  position: { x, y },
  visibility: {
    startVisible,
    requiredNodeIds: [],
    requiredItemIds: [],
    requiredInputMode: 'all',
    requiredInputCount: 1,
    hiddenUntilUnlocked: !startVisible,
  },
  scoring: { scoreForComplete: 0 },
  clues: [],
  codes: [],
  actions: [],
  agentUserIds: [],
})

